     4	
     5	/**
     6	 * Sends e-mails to guests. Every e-mail is kept in the list of sent messages. An invalid address is blocked; in
     7	 * test mode everything goes to the test inbox; otherwise a copy goes to the archive.
     8	 */
     9	public final class EmailSender {
    10	
    11	    static final String ARCHIVE = "arquivo@pousadamarealta.com.br";
    12	    static final String TEST_INBOX = "testes@pousadamarealta.com.br";
    13	    private static final Pattern VALID_ADDRESS = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
    14	
    15	    private final SentMessages sentMessages;
    16	    private final boolean testMode;
    17	
    18	    public EmailSender(SentMessages sentMessages) {
    19	        this(sentMessages, false);
    20	    }
    21	
    22	    public EmailSender(SentMessages sentMessages, boolean testMode) {
    23	        this.sentMessages = sentMessages;
    24	        this.testMode = testMode;
    25	    }
    26	
    27	    public Message send(String to, String subject, String body) {
    28	        if (!VALID_ADDRESS.matcher(to).matches()) {
    29	            return sentMessages.add("EMAIL", to, subject, body, MessageStatus.BLOCKED);
    30	        }
    31	        if (testMode) {
    32	            return sentMessages.add("EMAIL", TEST_INBOX, "[TESTE] " + subject,
    33	                    "Destinatário original: " + to + "\n" + body, MessageStatus.SENT);
    34	        }
    35	        Message original = sentMessages.add("EMAIL", to, subject, body, MessageStatus.SENT);
    36	        sentMessages.add("EMAIL", ARCHIVE, "[Cópia] " + subject, body, MessageStatus.SENT);
    37	        return original;
    38	    }
    39	}
