    17	    private final Javalin server;
    18	
    19	    public Hotel() {
    20	        Rooms rooms = new Rooms();
    21	        ReservationStore store = new ReservationStore();
    22	        SentMessages sentMessages = new SentMessages();
    23	        ReservationService reservations =
    24	                new ReservationService(rooms, store, new PriceCalculator(),
    25	                        new EmailSender(sentMessages, "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"))));
    26	        HttpApi api = new HttpApi(
    27	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
    28	        this.server = api.server();
    29	    }
