     1	package hotel.reservations;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	public final class Reservation {
     7	
     8	    private final long id;
     9	    private final int roomNumber;
    10	    private final Guest guest;
    11	    private final LocalDate checkIn;
    12	    private final LocalDate checkOut;
    13	    private final int guests;
    14	    private final RatePlan ratePlan;
    15	    private final Price price;
    16	    private ReservationStatus status;
    17	    private BigDecimal amountPaid;
    18	    private BigDecimal refund;
    19	
    20	    Reservation(long id, NewReservation request, Price price) {
    21	        this.id = id;
    22	        this.roomNumber = request.roomNumber();
    23	        this.guest = request.guest();
    24	        this.checkIn = request.checkIn();
    25	        this.checkOut = request.checkOut();
    26	        this.guests = request.guests();
    27	        this.ratePlan = request.ratePlan();
    28	        this.price = price;
    29	        this.status = ReservationStatus.PENDING;
    30	        this.amountPaid = PriceCalculator.cents(BigDecimal.ZERO);
    31	    }
    32	
    33	    public long id() {
    34	        return id;
    35	    }
    36	
    37	    public int roomNumber() {
    38	        return roomNumber;
    39	    }
    40	
    41	    public Guest guest() {
    42	        return guest;
    43	    }
    44	
    45	    public LocalDate checkIn() {
    46	        return checkIn;
    47	    }
    48	
    49	    public LocalDate checkOut() {
    50	        return checkOut;
    51	    }
    52	
    53	    public int guests() {
    54	        return guests;
    55	    }
    56	
    57	    public RatePlan ratePlan() {
    58	        return ratePlan;
    59	    }
    60	
    61	    public Price price() {
    62	        return price;
    63	    }
    64	
    65	    public ReservationStatus status() {
    66	        return status;
    67	    }
    68	
    69	    /** What the guest paid: the total, once the reservation is confirmed; zero before that. */
    70	    public BigDecimal amountPaid() {
    71	        return amountPaid;
    72	    }
    73	
    74	    /** What the guest got back when the reservation was cancelled; null while it is not cancelled. */
    75	    public BigDecimal refund() {
    76	        return refund;
    77	    }
    78	
    79	    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
    80	    public boolean isPaid() {
    81	        return status == ReservationStatus.CONFIRMED
    82	                || status == ReservationStatus.CHECKED_IN
    83	                || status == ReservationStatus.CHECKED_OUT;
    84	    }
    85	
    86	    /** The money the inn keeps from this reservation. */
    87	    public BigDecimal amountKept() {
    88	        return refund == null ? amountPaid : amountPaid.subtract(refund);
    89	    }
    90	
